class Solution {
public:
    int heightChecker(vector<int>& heights) {
        int count[101] = {};
        for (int h : heights) ++count[h];
        int expected = 1, mismatch = 0;
        for (int h : heights) {
            while (count[expected] == 0) ++expected;
            if (h != expected) ++mismatch;
            --count[expected];
        }
        return mismatch;
    }
};
